    // สร้าง Object ข้อมูลใหม่พร้อมแนบวันที่
    let newData = {
        "device": msg.payload.device,
        "code": currentCode,
        "signal_csq": msg.payload.signal_csq,
        "detail": msg.payload.detail,
        "timestamp": new Date().toLocaleString()
    };

    // นำข้อมูลใหม่ไปต่อท้าย Array
    dataList.push(newData);

    // จำกัดจำนวนสูงสุดไม่เกิน 10 ตัว (ถ้าเกินตัวแรกสุดจะถูกลบออก)
    if (dataList.length > 10) {
        dataList.shift();
    }

    // บันทึก Array กลับเข้า Flow
    flow.set("log", dataList);
}


// 6. ส่ง Array ทั้งหมดออกไปทาง msg.payload
msg.payload = dataList;

return msg;

// 1. ดึงข้อมูล Array ทั้งหมดจากระดับ Flow
let dataList = flow.get("myCollectedData") || [];

// 2. เช็คว่ามีข้อมูลเหลืออยู่หรือไม่
if (dataList.length > 0) {

    // เรียงลำดับจาก timestamp น้อยไปมาก (เก่าที่สุดอยู่ตำแหน่งแรกสุด index 0)
    dataList.sort((a, b) => a.timestamp - b.timestamp);

    // 3. .shift() จะหยิบข้อมูลตัวที่เก่าที่สุดออกมาจาก Array และลบมันออกจาก Array ทันที
    let itemToSend = dataList.shift();

    // 4. บันทึก Array ที่เหลืออยู่กลับลงไปใน Flow
    flow.set("myCollectedData", dataList);

    // 5. กำหนดให้ msg.payload เป็นข้อมูลตัวที่ถูกหยิบออกมาส่ง
    msg.payload = itemToSend;

    // ส่งข้อมูลออกไป
    return msg;

} else {
    // ถ้าไม่มีข้อมูลเหลือแล้ว ให้หยุดการส่ง
    return null; 
}

