// ========================================================
// Node-RED Function: ตรวจสอบการเปลี่ยนแปลงแบบแยกราย Tag (รูปแบบใหม่)
// ========================================================

const currentData = msg.payload;

// 1. ตรวจสอบความถูกต้องของโครงสร้างข้อมูล ป้องกันการ Error
if (!currentData || typeof currentData !== 'object') {
    return msg; // หากข้อมูลไม่ใช่ Object ให้ปล่อยผ่านไปก่อน
}

// 2. ดึงค่าพารามิเตอร์สำคัญของข้อมูลชุดปัจจุบัน
const currentTag = currentData.Tag || "Unknown";

// ดึงค่าสถานะ TO, TC, BATT และค่าในอาเรย์ raw / raw_2 ที่ต้องการเช็กการเปลี่ยนแปลง
const currentBatt = currentData.BATT !== undefined ? currentData.BATT : 0;
const currentReg0 = (currentData.raw && currentData.raw[0]) !== undefined ? currentData.raw[0] : 0;
const currentReg1 = (currentData.raw && currentData.raw[1]) !== undefined ? currentData.raw[1] : 0;
const currentPos  = (currentData.raw && currentData.raw[9]) !== undefined ? currentData.raw[9] : 0;
const currentTorq = (currentData.raw && currentData.raw[10]) !== undefined ? currentData.raw[10] : 0;

// ดึงค่า TO และ TC สำคัญๆ (สามารถเพิ่มลดได้ตามต้องการ)
const currentTO0  = currentData.TO0 !== undefined ? currentData.TO0 : 0;
const currentTC0  = currentData.TC0 !== undefined ? currentData.TC0 : 0;

// 3. ดึงฐานข้อมูลหน่วยความจำกลางระดับ Flow
var allDevicesMemory = flow.get("mov_devices_global_memory") || {};

// 4. ดึงข้อมูลล่าสุดเฉพาะของ Tag ตัวเองออกมาเช็ก
var lastSaved = allDevicesMemory[currentTag] || {};

// 5. 🎯 เปรียบเทียบข้อมูล (ถ้าค่าทุกตัวตรงกับประวัติเดิมเป๊ะ)
if (lastSaved.batt === currentBatt &&
    lastSaved.reg0 === currentReg0 &&
    lastSaved.reg1 === currentReg1 &&
    lastSaved.position === currentPos &&
    lastSaved.torque === currentTorq &&
    lastSaved.to0 === currentTO0 &&
    lastSaved.tc0 === currentTC0) {

    // 🚫 ข้อมูลของ Tag นี้ซ้ำเดิม -> คืนค่า null เพื่อบล็อกการส่งต่อ
    return null; 
}

// 6. 💾 ถ้าข้อมูลเปลี่ยนไป -> อัปเดตข้อมูลใหม่เฉพาะตำแหน่งคีย์ของ Tag ตัวเอง
allDevicesMemory[currentTag] = {
    batt: currentBatt,
    reg0: currentReg0,
    reg1: currentReg1,
    position: currentPos,
    torque: currentTorq,
    to0: currentTO0,
    tc0: currentTC0
};

// บันทึกกลุ่มข้อมูลทั้งหมดกลับเข้าสู่ระบบความจำส่วนกลางของ Flow Context
flow.set("mov_devices_global_memory", allDevicesMemory);

// 7. ส่งข้อมูล msg ของแท็กที่มีการอัปเดตออกไปทำงานต่อที่โหนดถัดไป
return msg;

